setup:
import {AuthConfig, buildClient, registerInstances} from 'webcommander-sdk';

registerInstances([
    new AuthConfig({
        clientName: 'default',
        grantType: 'client_credentials',
        baseUrl: process.env.WC_BASE_URL,
        clientId: process.env.WC_CLIENT_ID,
        clientSecret: process.env.WC_CLIENT_SECRET,
        redirectUri: process.env.WC_REDIRECT_URI,
        authString: process.env.WC_AUTH_STRING,
    }),
]);

const client = await buildClient(0, {raiseOnError: true});

list_customers.code:
const response = await client.adminCustomers.getCustomers({limit: 20, status: 'active'});
for (const customer of response.map.customers) {
    console.log(customer.customer_id, customer.email);
}

export_customers.code:
import {writeFileSync} from 'node:fs';

const response = await client.adminCustomers.getCustomerExport();
writeFileSync('customers.xlsx', response.map);

create_customer.code:
const response = await client.adminCustomers.createCustomer({
    customer: {first_name: 'Jane', last_name: 'Doe', email: 'jane@example.com', company: false},
});
console.log(response.map.customer.customer_id);

add_addresses.code:
const address = {
    type: 'shipping',
    first_name: 'Jane',
    last_name: 'Doe',
    address_line_1: '1 Example Street',
    city: 'Sydney',
    post_code: '2000',
};
const response = await client.adminCustomers.createCustomerAddresses(123, {customer: {addresses: [address]}});
console.log(response.map.customer.addresses);

change_password.code:
const response = await client.adminCustomers.changeCustomerPassword(123, {
    customer: {email: 'jane@example.com', old_password: 'OldPassw0rd!', password: 'NewPassw0rd!'},
});
console.log(response.map.status);

import_customers.code:
import {readFileSync} from 'node:fs';

const response = await client.adminCustomers.importCustomers({
    file: ['customers.csv', readFileSync('customers.csv'), 'text/csv'],
});
console.log(response.map.created, response.map.updated, response.map.failed);

list_store_credit_adjustments.code:
const response = await client.adminCustomers.getCustomerStoreCreditAdjustments(123, {limit: 20});
for (const adjustment of response.map.store_credit_adjustments) {
    console.log(adjustment.action, adjustment.amount);
}

adjust_store_credit.code:
const response = await client.adminCustomers.createCustomerStoreCreditAdjustment(123, {
    action: 'add',
    amount: 20,
    note: 'Refund',
});
console.log(response.map.store_credit);
